<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { SnackbarContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: SnackbarContract & { style?:string } = $props();
import {restoreInContext,ancestorChain,usable} from './modal-state.js';import {notificationLife} from './notification-life.svelte.js';let hover=$state(false),focused=$state(false);const life=notificationLife(()=>p.message?JSON.stringify([p.message.id,p.message.title,p.message.text,p.message.error,p.action,p.durationMs??null]):null,()=>p.durationMs??null,()=>hover||focused||Boolean(p.message?.actionPending),generation=>{if(p.message)p.onDismiss({id:p.message.id,reason:'timeout',generation});});let root=$state<HTMLElement>();function close(){if(p.message)p.onDismiss({id:p.message.id,reason:'close',generation:life.generation});}
let previous:string|null=null,initiator:HTMLElement|null=null,ancestors:HTMLElement[]=[];let alive=true;
$effect.pre(()=>{const revision=p.message?JSON.stringify([p.message.id,p.message.title,p.message.text,p.action]):null;const node=root,doc=node?.ownerDocument??(typeof document==='object'?document:undefined);if(!doc)return;if(previous===null&&revision!==null){initiator=doc.activeElement instanceof HTMLElement?doc.activeElement:null;ancestors=ancestorChain(initiator);}if(previous!==null&&revision!==previous&&node?.contains(doc.activeElement)){void tick().then(()=>{if(!alive)return;const active=doc.activeElement;if(active!==doc.body&&usable(active)&&!node.contains(active))return;restoreInContext(doc,initiator,p.fallbackFocusId,ancestors);});}previous=revision;});
onDestroy(()=>{alive=false;const node=root,doc=node?.ownerDocument;if(doc&&node?.contains(doc.activeElement)){const fallback=p.fallbackFocusId,target=initiator,chain=[...ancestors];queueMicrotask(()=>restoreInContext(doc,target,fallback,chain));}});

</script>
{#if p.message}<section style={p.style} bind:this={root} aria-label={p.message.title} {...owned('snackbar','root','open',p.message.actionPending&&'action-pending',p.message.error&&'error')} onpointerenter={()=>hover=true} onpointerleave={()=>hover=false} onfocusin={()=>focused=true} onfocusout={()=>void tick().then(()=>focused=root?.contains(document.activeElement)??false)}><div role="status"><h2 {...owned('snackbar','title')}>{p.message.title}</h2><p {...owned('snackbar','message',p.message.error&&'error')}>{p.message.text}</p>{#if p.message.error}<p>{p.message.error}</p>{/if}</div>{#if p.action}{#if p.action.kind==='link'}<a href={p.action.href} target={p.action.target} rel={p.action.target==='_blank'?'noopener noreferrer':p.action.rel} {...owned('snackbar','action')}>{p.action.label}{#if p.action.target==='_blank'}<span> (새 창)</span>{/if}</a>{:else}<button type="button" disabled={p.message.actionPending} {...owned('snackbar','action',p.message.actionPending&&'action-pending')} onclick={()=>{if(p.message&&p.action)p.onAction?.({id:p.message.id,generation:life.generation,actionId:p.action.id});}}>{p.action.label}</button>{/if}{/if}<button type="button" aria-label="알림 닫기" {...owned('snackbar','close')} onclick={close}>닫기</button></section>{/if}
